            color = grid[r][c]
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and not seen[ny][nx]
                            and grid[ny][nx] == color):
                        seen[ny][nx] = True
                        q.append((ny, nx))
            if len(cells) == 1 and color != background:
                singletons.append((r, c))
            elif len(cells) > 1 and color != background:
                ys = [y for y, x in cells]
                xs = [x for y, x in cells]
                components.append((color, min(ys), max(ys), min(xs), max(xs), len(cells)))

    out = [row[:] for row in grid]
    for r, c in singletons:
        neigh = [grid[y][x]
                 for y in range(max(0, r - 1), min(h, r + 2))
                 for x in range(max(0, c - 1), min(w, c + 2))
                 if (y, x) != (r, c)]
        votes = Counter(neigh)
        top = max(votes.values())
        tied = {v for v, n in votes.items() if n == top}
        if len(tied) == 1:
            out[r][c] = next(iter(tied))
            continue
        # A singleton falling inside a coherent object's bounding box is a hole
        # in that object; otherwise ties favor the global background.
        enclosed = [obj for obj in components if obj[1] <= r <= obj[2] and obj[3] <= c <= obj[4] and obj[0] in tied]
