def transform(grid):
    """Remove isolated speckles and repair holes in dense, rectangle-like patches."""
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = [[False] * w for _ in range(h)]
    components = []
    singletons = []
    for r in range(h):
        for c in range(w):
            if seen[r][c]:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and not seen[ny][nx]
                            and grid[ny][nx] == color):
                        seen[ny][nx] = True
                        q.append((ny, nx))
            if len(cells) == 1:
                singletons.append((color, cells[0][0], cells[0][1]))
            elif color != background:
                ys = [p[0] for p in cells]
                xs = [p[1] for p in cells]
                top, bottom, left, right = min(ys), max(ys), min(xs), max(xs)
                area = (bottom - top + 1) * (right - left + 1)
                # Treat dense component bounds as an intended rectangular patch.
                if len(cells) / area >= 0.72:
                    components.append((color, top, bottom, left, right, area))

    out = [row[:] for row in grid]
    # Reconstruct any corrupt cells inside a dense rectangular color patch.
    for color, top, bottom, left, right, area in components:
        for r in range(top, bottom + 1):
            for c in range(left, right + 1):
                out[r][c] = color
    # Isolated colored specks not inside one of the patches are background noise.
    for color, r, c in singletons:
        if color == background:
            continue
        enclosing = [obj for obj in components
                     if obj[1] <= r <= obj[2] and obj[3] <= c <= obj[4]]
        if not enclosing:
            out[r][c] = background
    return out
